"""Smoke tests of the runner against the real ffmpeg, ffprobe and fpcalc binaries."""

from __future__ import annotations

import json

import pytest

from provenance_kit.tools import run_tool, stream_tool

pytestmark = pytest.mark.integration

# 3 seconds of a 440 Hz tone, generated by ffmpeg itself: no media files needed.
TONE_WAV = [
    "-nostdin",
    "-hide_banner",
    "-loglevel",
    "error",
    "-f",
    "lavfi",
    "-i",
    "sine=frequency=440:sample_rate=22050:duration=3",
    "-f",
    "wav",
    "pipe:1",
]


def test_ffmpeg_reports_its_version(ffmpeg_path):
    result = run_tool(ffmpeg_path, ["-hide_banner", "-version"], tool="ffmpeg", timeout_seconds=60)
    assert result.stdout.startswith(b"ffmpeg version")


def test_ffmpeg_output_pipes_into_ffprobe(ffmpeg_path, ffprobe_path):
    wav = run_tool(ffmpeg_path, TONE_WAV, tool="ffmpeg", timeout_seconds=60).stdout
    probe = run_tool(
        ffprobe_path,
        [
            "-hide_banner",
            "-loglevel",
            "error",
            "-protocol_whitelist",
            "pipe",
            "-print_format",
            "json",
            "-show_streams",
            "-i",
            "pipe:0",
        ],
        tool="ffprobe",
        stdin=wav,
        timeout_seconds=60,
    )
    streams = json.loads(probe.stdout)["streams"]
    assert streams[0]["codec_type"] == "audio"
    assert int(streams[0]["sample_rate"]) == 22050


def test_ffmpeg_pipes_into_ffprobe_through_a_tool_process(ffmpeg_path, ffprobe_path):
    probe_args = [
        "-hide_banner",
        "-loglevel",
        "error",
        "-protocol_whitelist",
        "pipe",
        "-f",
        "wav",
        "-print_format",
        "json",
        "-show_streams",
        "-i",
        "pipe:0",
    ]
    with stream_tool(ffmpeg_path, TONE_WAV, tool="ffmpeg", timeout_seconds=60) as producer:
        probe = run_tool(
            ffprobe_path, probe_args, tool="ffprobe", stdin=producer, timeout_seconds=60
        )
    streams = json.loads(probe.stdout)["streams"]
    assert int(streams[0]["sample_rate"]) == 22050
    assert producer.bytes_read > 0
    assert not producer.output_limit_exceeded


def test_ffmpeg_streams_raw_pcm_records(ffmpeg_path):
    args = [*TONE_WAV[:-3], "-f", "s16le", "-ac", "1", "pipe:1"]
    frames = 0
    with stream_tool(ffmpeg_path, args, tool="ffmpeg", timeout_seconds=60) as proc:
        while proc.read_exact(2 * 2205) is not None:  # 0.1 s of mono s16 audio
            frames += 1
    assert frames == 30


def test_fpcalc_fingerprints_audio_from_stdin(ffmpeg_path, fpcalc_path):
    # A frequency sweep: a pure tone gives Chromaprint almost nothing to work with.
    sweep = "aevalsrc=sin(2*PI*(220+200*sin(2*PI*0.5*t))*t)+0.3*sin(2*PI*660*t):s=22050:d=12"
    base = ["-nostdin", "-hide_banner", "-loglevel", "error", "-f", "lavfi", "-i", sweep]
    base += ["-ac", "1"]
    wav = run_tool(ffmpeg_path, [*base, "-f", "wav", "pipe:1"], tool="ffmpeg").stdout
    pcm = run_tool(ffmpeg_path, [*base, "-f", "s16le", "pipe:1"], tool="ffmpeg").stdout

    from_wav = json.loads(run_tool(fpcalc_path, ["-json", "-"], tool="fpcalc", stdin=wav).stdout)
    raw_args = ["-json", "-format", "s16le", "-rate", "22050", "-channels", "1", "-"]
    from_pcm = json.loads(run_tool(fpcalc_path, raw_args, tool="fpcalc", stdin=pcm).stdout)

    assert len(from_wav["fingerprint"]) > 50
    assert from_wav["fingerprint"] == from_pcm["fingerprint"]
    # Known fpcalc behavior: with input on stdin it cannot know the duration and
    # reports 0.0. Backends must take the duration from ffprobe or the PCM size.
    assert from_wav["duration"] == 0.0
